custom_css:
/* ==========================================================
   VOID — YOUTH QUAKE / MoodTube theme v2
   Deep navy portable-player hardware, printed-paper details,
   worn plastic, blue-on-ivory accents. Built on MoodTube v2
   selectors and layered cover slots.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

@keyframes void-spin { to { transform: rotate(360deg); } }
@keyframes void-signal { 0%,100% { opacity: .55; } 50% { opacity: 1; } }

/* ---------- Core palette and slider variables ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
  --vq-navy: #10264A;
  --vq-deep: #08172F;
  --vq-mid: #183765;
  --vq-blue: #254B80;
  --vq-edge: #42689B;
  --vq-ice: #8FB9E8;
  --vq-paper: #F4F0E7;
  --vq-paper-dim: #DCD8CF;
  --vq-ink: #10264A;
  --vq-soft: #A8BCD7;
  --vq-red: #C95B60;

  --mt-text: var(--vq-paper);
  --mt-text-dim: var(--vq-soft);
  --mt-text-on-accent: var(--vq-deep);
  --mt-overlay: rgba(3, 10, 24, .82);
  --mt-modal-shadow: 0 12px 30px rgba(0,0,0,.36);
  --mt-text-strong: var(--vq-paper);
  --mt-divider: rgba(143,185,232,.25);
  --mt-pl-spotify-tab: var(--vq-ice);
  --mt-pl-spotify-tab-text: var(--vq-deep);

  --mt-slider-track: #091A34;
  --mt-slider-track-height: 5px;
  --mt-slider-track-radius: 0;
  --mt-slider-progress: var(--vq-ice);
  --mt-slider-thumb-size: 12px;
  --mt-slider-thumb-bg: var(--vq-paper);
  --mt-slider-thumb-bg-hover: var(--vq-ice);
  --mt-slider-thumb-border: 2px solid var(--vq-navy);
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: 0 0 0 1px var(--vq-ice);

  color: var(--vq-paper);
  scrollbar-color: var(--vq-edge) var(--vq-deep);
  scrollbar-width: thin;
}
#mt-settings-modal, #mt-settings-modal *, .mt-pl-modal, .mt-pl-modal *,
.mt-player, #moodtube-mini-player, #moodtube-mini-player *, .mt-fab {
  text-shadow: none;
}
.mt-player * { font-family: 'IBM Plex Mono', monospace; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* ---------- Main device shell ---------- */
.mt-player {
  padding: 40px 14px 15px;
  color: var(--vq-paper);
  background-color: var(--vq-navy);
  background-image:
    radial-gradient(rgba(244,240,231,.11) .65px, transparent .9px),
    linear-gradient(135deg, rgba(255,255,255,.055), transparent 42%),
    linear-gradient(315deg, rgba(0,0,0,.20), transparent 48%);
  background-size: 6px 6px, auto, auto;
  border: 2px solid #355786;
  border-radius: 15px;
  box-shadow: inset 0 0 0 3px rgba(5,17,36,.55), 0 5px 0 rgba(3,10,24,.35);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  overflow: hidden;
}
.mt-player::before {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(143,185,232,.23);
  border-radius: 10px;
  pointer-events: none;
  z-index: 1;
}
.mt-player::after {
  content: 'VOID  •  V.02';
  position: absolute;
  bottom: 5px;
  right: 14px;
  color: rgba(244,240,231,.46);
  font: 500 8px 'IBM Plex Mono', monospace;
  letter-spacing: 1.5px;
  pointer-events: none;
  z-index: 4;
}
.mt-slot-bg { opacity: .12; }
.mt-slot-scene { opacity: .1; }
.mt-slot-decor { z-index: 1; opacity: .72; pointer-events: none; }

/* ---------- Title bar and window controls ---------- */
.mt-player:not(.moodtube-row-layout) .mt-player-header { display: contents; }
.mt-player-header { right: 96px; }
.mt-player:not(.moodtube-row-layout) .mt-player-header-title {
  position: absolute; top: 10px; left: 15px; z-index: 6;
}
.mt-player-header-title {
  color: var(--vq-paper);
  font: 800 17px 'Barlow Condensed', sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}
.mt-player-status {
  color: var(--vq-ice);
  font: 500 9px 'IBM Plex Mono', monospace;
  letter-spacing: .5px;
}
.mt-player:not(.moodtube-row-layout) .mt-player-status {
  position: absolute; z-index: 3; top: 184px; left: 24px;
  font-size: 9px;
}
.mt-is-playing .mt-player-status { animation: void-signal 2.4s ease-in-out infinite; }
.mt-window-btn {
  top: 8px; width: 20px; height: 20px; box-sizing: border-box;
  display: flex; align-items: center; justify-content: center;
  color: var(--vq-paper); font-size: 10px;
  background: #1A3763; border: 1px solid #5679A8; border-radius: 4px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.12);
}
.mt-window-btn:hover { color: var(--vq-deep); background: var(--vq-ice); }
.mt-btn-search { right: 64px; }
.mt-btn-settings { right: 38px; }
.mt-btn-close { right: 12px; }
.mt-btn-close:hover { color: white; background: var(--vq-red); border-color: var(--vq-red); }

/* ---------- Cover panel: turntable-inspired record ---------- */
.mt-player-body { gap: 8px; justify-content: flex-start; }
.mt-player:not(.moodtube-row-layout) .mt-cover {
  width: 222px; max-width: 100%; height: 130px; box-sizing: border-box;
  align-self: center; border-radius: 7px;
  border: 1px solid #587AA7;
  background: linear-gradient(145deg, #193762, #08172F);
  box-shadow: inset 0 0 0 3px rgba(3,12,28,.55), 0 2px 0 rgba(0,0,0,.3);
  overflow: hidden;
}
.mt-player:not(.moodtube-row-layout) .mt-slot-cover-bg {
  background-size: 100% 100%;
  opacity: .95;
}
.mt-player:not(.moodtube-row-layout) .mt-slot-cover {
  z-index: 3;
  background-size: 100% 100%;
  transform-origin: 86.5% 15.4%;
  transform: rotate(-26deg);
  transition: transform .6s ease-in-out;
}
.mt-player.mt-is-playing:not(.moodtube-row-layout) .mt-slot-cover { transform: rotate(0deg); }
.mt-player:not(.moodtube-row-layout) .mt-cover-img {
  width: 40px; height: 40px; flex: none;
  background: var(--vq-paper);
  border: 2px solid var(--vq-ice);
  box-shadow: 0 0 0 2px rgba(8,23,47,.8);
  position: relative; z-index: 2;
}
.mt-player.mt-is-playing .mt-cover-img { animation: void-spin 5s linear infinite; }
.mt-player:not(.moodtube-row-layout) .mt-cover-hole {
  width: 6px; height: 6px; z-index: 2;
  background: var(--vq-deep); border: 1px solid var(--vq-paper);
}

/* ---------- Track metadata: paper label against navy hardware ---------- */
.mt-player:not(.moodtube-row-layout) .mt-track-info {
  align-items: flex-start; text-align: left;
  color: var(--vq-ink);
  background-color: var(--vq-paper);
  background-image: radial-gradient(rgba(16,38,74,.12) .6px, transparent .85px);
  background-size: 5px 5px;
  border: 1px solid #B5C5D9;
  border-radius: 5px;
  padding: 16px 26px 6px 9px;
  box-shadow: 2px 2px 0 rgba(0,0,0,.18);
}
.mt-track-title {
  color: var(--vq-ink); font: 800 17px 'Barlow Condensed', sans-serif;
  line-height: 1.1; letter-spacing: .35px; text-transform: uppercase;
  margin-bottom: 1px;
}
.mt-track-subtitle { color: #536987; font: 500 10px 'IBM Plex Mono', monospace; }
.mt-btn-favorite { color: #345784; font-size: 14px; right: 7px; top: 6px; }
.mt-btn-favorite:hover, .mt-btn-favorite.mt-is-active { color: var(--vq-red); }

/* ---------- Progress and volume ---------- */
.mt-progress { margin-top: 0; color: var(--vq-soft); font: 500 10px 'IBM Plex Mono', monospace; }
.mt-time-current, .mt-time-total { color: var(--vq-soft); font: 500 10px 'IBM Plex Mono', monospace; }
.mt-volume { width: 100%; color: var(--vq-soft); }
.mt-volume-icon { color: var(--vq-ice); }
.mt-progress-slider, .mt-volume-slider { accent-color: var(--vq-ice); }

/* ---------- Tactile hardware buttons ---------- */
.mt-controls { gap: 6px; }
.mt-controls > .mt-btn {
  width: 34px; height: 30px; box-sizing: border-box;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; color: var(--vq-paper);
  background: linear-gradient(180deg, #244879, #152F55);
  border: 1px solid #5679A8; border-radius: 7px;
  box-shadow: 0 2px 0 #08172F, inset 0 1px 0 rgba(255,255,255,.12);
  transition: transform .12s ease, background .12s ease, color .12s ease;
}
.mt-controls > .mt-btn-play {
  width: 44px; height: 34px; font-size: 15px;
  color: var(--vq-deep); background: var(--vq-ice);
  border-color: #B5D2F2;
  box-shadow: 0 2px 0 #07142A, inset 0 1px 0 rgba(255,255,255,.5);
}
.mt-controls > .mt-btn:hover {
  transform: translateY(-1px); color: var(--vq-deep);
  background: #B5D2F2; border-color: #D5E6F8;
}
.mt-controls > .mt-btn-play:hover { color: var(--vq-deep); background: #D5E6F8; }
.mt-controls > .mt-btn:active { transform: translateY(2px); box-shadow: 0 0 0 #08172F; }
.mt-btn-ai.mt-is-busy { color: var(--vq-ice); }

/* ---------- Queue and playlist panels ---------- */
.mt-panel {
  color: var(--vq-paper); background: var(--vq-navy);
  background-image: radial-gradient(rgba(244,240,231,.08) .65px, transparent .9px);
  background-size: 6px 6px;
  padding-top: 42px;
}
.mt-panel-header { border-bottom: 1px solid rgba(143,185,232,.25); }
.mt-panel-title { color: var(--vq-paper); font: 700 12px 'IBM Plex Mono', monospace; letter-spacing: .8px; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--vq-ice); }
.mt-queue-item, .mt-playlist-item {
  color: var(--vq-paper); background: #162F55;
  border: 1px solid rgba(143,185,232,.16); border-radius: 5px;
}
.mt-queue-item:hover, .mt-playlist-item:hover { background: #214574; }
.mt-queue-item.mt-is-current { background: #1C3B68; border-color: var(--vq-ice); }
.mt-queue-thumb { border-radius: 3px; border: 1px solid var(--vq-edge); box-sizing: border-box; }
.mt-queue-thumb.mt-is-empty { background: #244879; }
.mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--vq-paper); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #A8BCD7; }
.mt-queue-now, .mt-queue-add { color: var(--vq-ice); }
.mt-queue-dislike { background-color: var(--vq-red); }
.mt-queue-empty { color: var(--vq-soft); }
.mt-resize-handle i { color: var(--vq-ice); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
  color: var(--vq-deep);
  background: var(--vq-ice);
  border: 1px solid #C5DDF5;
  box-shadow: 0 3px 0 #07142A;
}
.mt-fab:hover { color: var(--vq-deep); background: #D5E6F8; }

/* ---------- Settings modal ---------- */
#mt-settings-modal {
  --mt-text: var(--vq-paper);
  --mt-text-dim: var(--vq-soft);
  --mt-text-on-accent: var(--vq-deep);
  --mt-overlay: rgba(3,10,24,.84);
  --mt-modal-shadow: 0 12px 30px rgba(0,0,0,.38);
  --mt-text-strong: var(--vq-paper);
  --mt-divider: rgba(143,185,232,.25);
  color: var(--vq-paper);
}
#mt-settings-modal .mt-flex-container {
  color: var(--vq-paper);
  background: var(--vq-navy);
  background-image: radial-gradient(rgba(244,240,231,.07) .65px, transparent .9px);
  background-size: 6px 6px;
  border: 2px solid #355786; border-radius: 12px;
  box-shadow: inset 0 0 0 3px rgba(5,17,36,.45);
  backdrop-filter: none;
}
#mt-settings-modal .mt-header h3 { color: var(--vq-paper); font-family: 'Barlow Condensed', sans-serif; font-weight: 800; letter-spacing: 1px; text-transform: uppercase; }
#mt-settings-modal .mt-close { color: var(--vq-ice); }
#mt-settings-modal .mt-content { scrollbar-color: var(--vq-edge) transparent; }
#mt-settings-modal .mt-content::-webkit-scrollbar-thumb { background-color: var(--vq-edge); }
#mt-settings-modal .mt-cat-title:hover { background-color: rgba(143,185,232,.08); }
#mt-settings-modal .mt-subpanel {
  color: var(--vq-paper); background: #142D52;
  border: 1px solid rgba(143,185,232,.24); border-radius: 7px;
}
#mt-settings-modal input, #mt-settings-modal select, #mt-settings-modal textarea {
  color: var(--vq-paper); background: #08172F;
  border: 1px solid #42689B; border-radius: 4px;
}
#mt-settings-modal input::placeholder, #mt-settings-modal textarea::placeholder { color: #8EA5C5; opacity: 1; }
#mt-settings-modal input:focus, #mt-settings-modal select:focus, #mt-settings-modal textarea:focus {
  border-color: var(--vq-ice); outline: 1px solid rgba(143,185,232,.4);
}
#mt-settings-modal .mt-tag, #mt-settings-modal .mt-genre-tag,
#mt-settings-modal .mt-mood-tag, #mt-settings-modal .mt-scenario-tag {
  color: var(--vq-paper); background: #193762;
  border: 1px solid #42689B; border-radius: 4px; box-shadow: none;
}
#mt-settings-modal .mt-tag:hover, #mt-settings-modal .mt-genre-tag:hover,
#mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
  color: var(--vq-deep); background: #B5D2F2; border-color: var(--vq-ice);
}
#mt-settings-modal .mt-tag.active, #mt-settings-modal .mt-genre-tag.active,
#mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
  color: var(--vq-deep); background: var(--vq-ice); border-color: #D5E6F8; box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test {
  color: var(--vq-deep); background: var(--vq-ice); border: 1px solid #B5D2F2;
  border-radius: 4px; font: 600 11px 'IBM Plex Mono', monospace;
}
#mt-settings-modal .mt-btn-test:hover { color: var(--vq-deep); background: #D5E6F8; }
#mt-settings-modal .mt-catalog-preview { background: #193762; color: var(--vq-soft); }
#mt-settings-modal .mt-catalog-tag { background: #193762; color: var(--vq-soft); }

/* ---------- Search panel, playlists, and modal ---------- */
.mt-panel-search { --mt-bg-primary: var(--vq-navy); background: var(--vq-navy); }
#moodtube-search-input {
  color: var(--vq-paper); background: #08172F;
  border: 1px solid #42689B; border-radius: 4px;
  font: 500 11px 'IBM Plex Mono', monospace;
}
#moodtube-search-input::placeholder { color: #8EA5C5; opacity: 1; }
#moodtube-search-input:focus { border-color: var(--vq-ice); outline: 1px solid rgba(143,185,232,.4); }
#moodtube-search-container #moodtube-search-go {
  color: var(--vq-deep); background: var(--vq-ice);
  border: 1px solid #B5D2F2; border-radius: 4px;
}
#moodtube-search-container #moodtube-search-go:hover { background: #D5E6F8; }
.mt-pl-tabs { background: #0B1B35; border-bottom: 1px solid rgba(143,185,232,.25); }
.mt-pl-tab { color: var(--vq-soft); }
.mt-pl-tab:hover { color: var(--vq-paper); background: #193762; }
.mt-pl-tab.mt-is-active { color: var(--vq-deep); background: var(--vq-ice); }
.mt-pl-cover { background: #193762; border: 1px solid var(--vq-edge); }
.mt-pl-cover-empty { background: #193762; color: var(--vq-soft); }
.mt-pl-count { color: var(--vq-soft); }
.mt-pl-tool { color: var(--vq-paper); background: #193762; border: 1px solid var(--vq-edge); }
.mt-pl-tool:hover { color: var(--vq-deep); background: var(--vq-ice); }
.mt-pl-tool.mt-pl-play { color: var(--vq-deep); background: var(--vq-ice); border-color: var(--vq-ice); }
.mt-pl-inline { color: var(--vq-paper); background: #08172F; border: 1px solid var(--vq-edge); }
.mt-pl-inline-cancel { color: var(--vq-ice); }
.mt-pl-modal-box {
  color: var(--vq-paper); background: var(--vq-navy);
  border: 2px solid #355786; border-radius: 12px;
  box-shadow: 0 8px 0 rgba(0,0,0,.28);
}
.mt-pl-modal-track { color: var(--vq-paper); border-bottom: 1px solid rgba(143,185,232,.25); }
.mt-pl-modal-close { color: var(--vq-ice); }
.mt-pl-option { color: var(--vq-paper); background: #162F55; border: 1px solid transparent; border-radius: 5px; }
.mt-pl-option:hover { background: #214574; border-color: var(--vq-edge); }
.mt-pl-option.mt-is-added { color: var(--vq-deep); background: var(--vq-ice); border-color: var(--vq-ice); }

/* ---------- Dock strip ---------- */
#moodtube-dock {
  font-family: 'IBM Plex Mono', monospace;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border: 1.5px solid var(--vq-edge); }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%; font-size: 12px; color: var(--vq-paper);
  background: #193762; border: 1px solid #42689B;
  transition: background-color .15s ease;
}
#moodtube-dock .mt-dock-btn:hover { color: var(--vq-deep); background: var(--vq-ice); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  color: var(--vq-deep); background: var(--vq-ice); border-color: var(--vq-ice);
}
#moodtube-dock .mt-dock-play:hover { background: #D5E6F8; color: var(--vq-deep); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--vq-paper); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--vq-ice); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--vq-soft); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open { color: var(--vq-paper); background: #244879; }
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}

/* ---------- Layout adaptation ---------- */
.mt-player.moodtube-no-cover .mt-cover { display: none; }
.mt-player.moodtube-no-vol .mt-volume, .mt-player.moodtube-no-vol .mt-progress { display: none; }
.mt-player.moodtube-no-title .mt-player-header-title { display: none; }

.mt-player.moodtube-row-layout .mt-player-body {
  display: flex; flex-direction: row; align-items: center; gap: 8px; min-width: 0;
}
.mt-player.moodtube-row-layout .mt-cover {
  width: 50px; height: 50px; min-width: 50px; min-height: 50px;
  flex: 0 0 50px; margin: 0; border-width: 1px; box-shadow: none;
}
.mt-player.moodtube-row-layout .mt-track-info {
  width: auto; min-width: 100px; max-width: 150px; flex: 1 1 115px;
  text-align: left; padding-right: 16px;
}
.mt-player.moodtube-row-layout .mt-track-title { font-size: 13px; }
.mt-player.moodtube-row-layout .mt-track-subtitle { font-size: 10px; }
.mt-player.moodtube-row-layout .mt-progress { width: auto; min-width: 90px; flex: 1 1 100px; gap: 5px; }
.mt-player.moodtube-row-layout .mt-controls { width: auto; flex: 0 0 auto; gap: 4px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 24px; height: 24px; font-size: 10px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 34px; height: 34px; font-size: 14px; }
.mt-player.moodtube-row-layout .mt-volume { width: 66px; flex: 0 1 66px; gap: 4px; }
@container (max-width: 640px) {
  .mt-player.moodtube-row-layout .mt-volume { display: none; }
}
@container (max-width: 420px) {
  .mt-player.moodtube-row-layout .mt-player-body { gap: 5px; }
  .mt-player.moodtube-row-layout .mt-cover { width: 42px; height: 42px; min-width: 42px; min-height: 42px; flex-basis: 42px; }
  .mt-player.moodtube-row-layout .mt-track-info { min-width: 90px; flex-basis: 90px; }
  .mt-player.moodtube-row-layout .mt-progress { min-width: 75px; }
  .mt-player.moodtube-row-layout .mt-controls { gap: 3px; }
  .mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 22px; height: 22px; font-size: 10px; }
  .mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 30px; height: 30px; font-size: 12px; }
}
@container (max-width: 300px) {
  .mt-player .mt-player-status { display: none; }
}
@container (max-width: 190px) {
  .mt-player { padding: 32px 8px 12px; }
  .mt-player .mt-player-header { left: 10px; right: 78px; font-size: 9px; }
  .mt-player .mt-cover { width: 66px; height: 66px; min-width: 66px; min-height: 66px; }
  .mt-player .mt-track-title { font-size: 12px; }
  .mt-player .mt-track-subtitle { font-size: 10px; }
  .mt-player .mt-controls { gap: 4px; }
  .mt-player .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 11px; }
  .mt-player .mt-controls > .mt-btn-play { width: 30px; height: 30px; font-size: 12px; }
}
@container (max-height: 250px) {
  .mt-player { padding-top: 30px; padding-bottom: 10px; }
  .mt-player .mt-player-body { gap: 6px; }
}

/* Focus and motion accessibility */
.mt-player button:focus-visible, #mt-settings-modal button:focus-visible,
.mt-fab:focus-visible, .mt-pl-modal button:focus-visible {
  outline: 2px solid var(--vq-ice); outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .mt-player *, #mt-settings-modal *, .mt-pl-modal *, .mt-fab { animation: none !important; transition-duration: 0s !important; }
}

.mt-player { container-type: size; } /* the theme's @container rules need a container to measure */
.mt-queue-title { font-size: 11px; letter-spacing: 0; }
.mt-queue-thumb { width: 26px; height: 26px; }
/* fixes: status text sits on the ivory label (ice blue was unreadable there); in the wide row the title lost its paper label and navy text vanished on navy */
.mt-player:not(.moodtube-row-layout) .mt-player-status { color: #345784; }
.mt-player.moodtube-row-layout .mt-track-title { color: var(--vq-paper); }
.mt-player.moodtube-row-layout .mt-track-subtitle { color: var(--vq-soft); }
.mt-player.moodtube-row-layout .mt-btn-favorite { color: var(--vq-ice); }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 6px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 10px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 42px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 74px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 106px; left: auto; }
#moodtube-mini-player .mt-player-header-title { font-size: 15px; letter-spacing: 1.4px; }
